60	/// An RAII object that represents a read-only tflite model, copied from disk,
61	/// or mmapped. This uses flatbuffers as the serialization format.
62	///
63	/// NOTE: The current API requires that a FlatBufferModelBase instance be kept
64	/// alive by the client as long as it is in use by any dependent Interpreter
65	/// instances. As the FlatBufferModelBase instance is effectively immutable
66	/// after creation, the client may safely use a single model with multiple
67	/// dependent Interpreter instances, even across multiple threads (though note
68	/// that each Interpreter instance is *not* thread-safe).
69	///
70	/// <pre><code>
71	/// using namespace tflite;
72	/// StderrReporter error_reporter;
73	/// auto model = FlatBufferModelBase::BuildFromFile("interesting_model.tflite",
74	///                                             &error_reporter);
75	/// MyOpResolver resolver;  // You need to subclass OpResolver to provide
76	///                         // implementations.
77	/// InterpreterBuilder builder(*model, resolver);
78	/// std::unique_ptr<Interpreter> interpreter;
79	/// if(builder(&interpreter) == kTfLiteOk) {
80	///   .. run model inference with interpreter
81	/// }
82	/// </code></pre>
83	///
84	/// OpResolver must be defined to provide your kernel implementations to the
85	/// interpreter. This is environment specific and may consist of just the
86	/// builtin ops, or some custom operators you defined to extend tflite.
87	template <typename T>
88	class FlatBufferModelBase {
89	 public:
90	  /// Builds a model based on a file.
91	  /// Caller retains ownership of `error_reporter` and must ensure its lifetime
92	  /// is longer than the FlatBufferModelBase instance.
93	  /// Returns a nullptr in case of failure.
94	  static std::unique_ptr<T> BuildFromFile(
95	      const char* filename,
96	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter()) {
97	    error_reporter = ValidateErrorReporter(error_reporter);
98	    std::unique_ptr<T> model = BuildFromAllocation(
99	        GetAllocationFromFile(filename, error_reporter), error_reporter);
100	#if FLATBUFFERS_LITTLEENDIAN == 1
101	    return model;
102	#else
103	    return ByteConvertModel(std::move(model), error_reporter);
104	#endif
105	  }
106	
107	  /// Verifies whether the content of the file is legit, then builds a model
108	  /// based on the file.
109	  /// The extra_verifier argument is an additional optional verifier for the
110	  /// file contents. By default, we always check with tflite::VerifyModelBuffer.
111	  /// If extra_verifier is supplied, the file contents is also checked against
112	  /// the extra_verifier after the check against tflite::VerifyModelBuilder.
113	  /// Caller retains ownership of `error_reporter` and must ensure its lifetime
114	  /// is longer than the FlatBufferModelBase instance.
115	  /// Returns a nullptr in case of failure.
116	  static std::unique_ptr<T> VerifyAndBuildFromFile(
117	      const char* filename, TfLiteVerifier* extra_verifier = nullptr,
118	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter()) {
119	    error_reporter = ValidateErrorReporter(error_reporter);
120	    std::unique_ptr<T> model = VerifyAndBuildFromAllocation(
121	        GetAllocationFromFile(filename, error_reporter), extra_verifier,
122	        error_reporter);
123	#if FLATBUFFERS_LITTLEENDIAN == 1
124	    return model;
125	#else
126	    return ByteConvertModel(std::move(model), error_reporter);
127	#endif
128	  }
