211	  static void ByteSwapSerializedModel(std::string* serialized_model,
212	                                      bool from_big_endian) {
213	    const uint8_t* buffer =
214	        reinterpret_cast<const uint8_t*>(serialized_model->c_str());
215	    const tflite::Model* input_model = tflite::GetModel(buffer);
216	    ByteSwapTFLiteModel(input_model, from_big_endian);
217	  }
218	
219	  static void ByteSwapBuffer(int8_t tensor_type, size_t buffer_size,
220	                             uint8_t* buffer, bool from_big_endian) {
221	    switch (tensor_type) {
222	      case tflite::TensorType_STRING: {
223	        auto bp = reinterpret_cast<int32_t*>(buffer);
224	        int num_of_strings =
225	            from_big_endian ? bp[0] : flatbuffers::EndianSwap(bp[0]);
226	        for (int i = 0; i < num_of_strings + 2; i++)
227	          bp[i] = flatbuffers::EndianSwap(bp[i]);
228	        break;
229	      }
230	      // 16-bit types
231	      case tflite::TensorType_FLOAT16:
232	      case tflite::TensorType_INT16:
233	      case tflite::TensorType_UINT16: {
234	        auto bp = reinterpret_cast<uint16_t*>(buffer);
235	        for (int i = 0; i < buffer_size / 2; i++)
236	          bp[i] = flatbuffers::EndianSwap(bp[i]);
237	        break;
238	      }
239	      // 32-bit types
240	      case tflite::TensorType_FLOAT32:
241	      case tflite::TensorType_INT32:
242	      case tflite::TensorType_UINT32:
243	      case tflite::TensorType_COMPLEX64: {
244	        auto bp = reinterpret_cast<uint32_t*>(buffer);
245	        for (int i = 0; i < buffer_size / 4; i++)
246	          bp[i] = flatbuffers::EndianSwap(bp[i]);
247	        break;
248	      }
249	      // 64-bit types
250	      case tflite::TensorType_INT64:
251	      case tflite::TensorType_FLOAT64:
252	      case tflite::TensorType_UINT64:
253	      case tflite::TensorType_COMPLEX128: {
254	        auto bp = reinterpret_cast<uint64_t*>(buffer);
255	        for (int i = 0; i < buffer_size / 8; i++)
256	          bp[i] = flatbuffers::EndianSwap(bp[i]);
257	        break;
258	      }
259	      default:
260	        break;
261	    }
262	  }
263	
264	  static void ByteSwapTFLiteModel(const tflite::Model* tfl_model,
265	                                  bool from_big_endian) {
266	    std::vector<bool> buffer_swapped(tfl_model->buffers()->size(), false);
267	    for (size_t subgraph_idx = 0; subgraph_idx < tfl_model->subgraphs()->size();
268	         subgraph_idx++) {
269	      const tflite::SubGraph* subgraph =
270	          tfl_model->subgraphs()->Get(subgraph_idx);
271	      for (size_t ts_idx = 0; ts_idx < subgraph->tensors()->size(); ts_idx++) {
272	        const tflite::Tensor* tensor = subgraph->tensors()->Get(ts_idx);
273	        if (tensor->buffer() > 0 &&
274	            tensor->buffer() < tfl_model->buffers()->size() &&
275	            !buffer_swapped[tensor->buffer()]) {
276	          const tflite::Buffer* buffer_ =
277	              (*tfl_model->buffers())[tensor->buffer()];
278	          if (!buffer_ || !buffer_->data()) continue;
279	          auto* buffer = buffer_->data();
280	          uint8_t* buff_ = const_cast<uint8_t*>(buffer->data());
281	          ByteSwapBuffer(tensor->type(), buffer->size(), buff_,
282	                         from_big_endian);
283	          buffer_swapped[tensor->buffer()] = true;
284	        }
285	      }
286	    }
287	  }
288	
289	  static std::unique_ptr<T> ByteConvertModel(std::unique_ptr<T> model,
290	                                             ErrorReporter* error_reporter,
291	                                             bool from_big_endian = false) {
292	    if (model == nullptr) return model;
293	    auto tfl_model = model->GetModel();
294	    if (tfl_model->subgraphs()->size() == 0) return model;
295	    if (tfl_model->subgraphs()->Get(0)->tensors()->size() == 0) return model;
296	    if (tfl_model->buffers()->size() < 2) return model;
297	    return ByteSwapFlatBufferModelBase(std::move(model), error_reporter,
298	                                       from_big_endian);
299	  }
300	
301	  static std::unique_ptr<T> ByteSwapFlatBufferModelBase(
302	      std::unique_ptr<T> model, ErrorReporter* error_reporter,
303	      bool from_big_endian) {
304	    FlatBufferModelBase<T>* modelp = model.release();
305	    auto tflite_model = modelp->GetModel();
306	    auto copied_model = std::make_unique<tflite::ModelT>();
307	    tflite_model->UnPackTo(copied_model.get(), nullptr);
308	    ByteSwapTFLiteModelT(copied_model.get(), from_big_endian);
309	    std::unique_ptr<flatbuffers::FlatBufferBuilder> builder(
310	        new flatbuffers::FlatBufferBuilder());
311	    auto packed_model = tflite::Model::Pack(*builder, copied_model.get());
312	    tflite::FinishModelBuffer(*builder, packed_model);
313	    flatbuffers::FlatBufferBuilder* builder_ = builder.release();
314	    return BuildFromBuffer(
315	        reinterpret_cast<const char*>(builder_->GetBufferPointer()),
316	        builder_->GetSize(), error_reporter);
317	  }
318	
319	  static void ByteSwapTFLiteModelT(tflite::ModelT* tfl_modelt,
320	                                   bool from_big_endian) {
321	    size_t bytes_per_elem = 0;
322	    std::vector<bool> buffer_swapped(tfl_modelt->buffers.size(), false);
323	    for (size_t subgraph_idx = 0; subgraph_idx < tfl_modelt->subgraphs.size();
324	         subgraph_idx++) {
325	      tflite::SubGraphT* subgraph =
326	          tfl_modelt->subgraphs.at(subgraph_idx).get();
327	      for (size_t ts_idx = 0; ts_idx < subgraph->tensors.size(); ts_idx++) {
328	        tflite::TensorT* tensor = subgraph->tensors[ts_idx].get();
329	        if (tensor->buffer > 0 && tensor->buffer < tfl_modelt->buffers.size() &&
330	            !buffer_swapped[tensor->buffer]) {
331	          const auto* buffer =
332	              &(tfl_modelt->buffers[tensor->buffer].get()->data);
333	          if (buffer && buffer->data()) {
334	            uint8_t* buff_ = const_cast<uint8_t*>(buffer->data());
335	            ByteSwapBuffer(tensor->type, buffer->size(), buff_,
336	                           from_big_endian);
337	            buffer_swapped[tensor->buffer] = true;
338	          }
339	        }
340	      }
341	    }
342	  }
