347	  // Internal helper to build a model from an allocation without running base
348	  // verification.
349	  static std::unique_ptr<T> BuildFromAllocationInternal(
350	      std::unique_ptr<Allocation> allocation, ErrorReporter* error_reporter) {
351	    std::unique_ptr<T> model(new T(std::move(allocation), error_reporter));
352	    if (!model->initialized()) {
353	      model.reset();
354	    } else {
355	      model->ValidateModelBuffers(model->error_reporter());
356	    }
357	    return model;
