360	 public:
361	  /// Builds a model directly from an allocation.
362	  /// Ownership of the allocation is passed to the model, but the caller
363	  /// retains ownership of `error_reporter` and must ensure its lifetime is
364	  /// longer than the FlatBufferModelBase instance.
365	  /// Returns a nullptr in case of failure (e.g., the allocation is invalid).
366	  static std::unique_ptr<T> BuildFromAllocation(
367	      std::unique_ptr<Allocation> allocation,
368	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter()) {
369	    error_reporter = ValidateErrorReporter(error_reporter);
370	    if (!allocation || !allocation->valid()) {
371	      TF_LITE_REPORT_ERROR(error_reporter,
372	                           "The model allocation is null/empty");
373	      return nullptr;
374	    }
375	    return BuildFromAllocationInternal(std::move(allocation), error_reporter);
376	  }
377	
378	  /// Verifies whether the content of the allocation is legit, then builds a
379	  /// model based on the provided allocation.
380	  /// The extra_verifier argument is an additional optional verifier for the
381	  /// buffer. By default, we always check with tflite::VerifyModelBuffer. If
382	  /// extra_verifier is supplied, the buffer is checked against the
383	  /// extra_verifier after the check against tflite::VerifyModelBuilder.
384	  /// Ownership of the allocation is passed to the model, but the caller
385	  /// retains ownership of `error_reporter` and must ensure its lifetime is
386	  /// longer than the FlatBufferModelBase instance.
387	  /// Returns a nullptr in case of failure.
388	  static std::unique_ptr<T> VerifyAndBuildFromAllocation(
389	      std::unique_ptr<Allocation> allocation,
390	      TfLiteVerifier* extra_verifier = nullptr,
391	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter()) {
392	    error_reporter = ValidateErrorReporter(error_reporter);
393	    if (!allocation || !allocation->valid()) {
394	      TF_LITE_REPORT_ERROR(error_reporter,
395	                           "The model allocation is null/empty");
396	      return nullptr;
397	    }
398	
399	    {
400	      // Flatbuffers can only be smaller than 2GB. The file format appends some
401	      // data after the actual flabuffer. We truncate the allocation size to 2GB
402	      // so that the verifier doesn't early exit on us.
403	      size_t allocation_size =
404	          std::min(allocation->bytes(),
405	                   static_cast<size_t>(FLATBUFFERS_MAX_BUFFER_SIZE - 1));
406	      flatbuffers::Verifier base_verifier(
407	          reinterpret_cast<const uint8_t*>(allocation->base()), allocation_size,
408	          flatbuffers::Verifier::Options());
409	      if (!VerifyModelBuffer(base_verifier)) {
410	        TF_LITE_REPORT_ERROR(error_reporter,
411	                             "The model is not a valid Flatbuffer buffer");
412	        return nullptr;
413	      }
414	
415	      if (extra_verifier &&
416	          !extra_verifier->Verify(static_cast<const char*>(allocation->base()),
417	                                  allocation_size, error_reporter)) {
418	        // The verifier will have already logged an appropriate error message.
419	        return nullptr;
420	      }
421	    }
422	
423	    return BuildFromAllocationInternal(std::move(allocation), error_reporter);
424	  }
