426	  /// Builds a model directly from a flatbuffer pointer
427	  /// Caller retains ownership of the buffer and should keep it alive until the
428	  /// returned object is destroyed. Caller retains ownership of `error_reporter`
429	  /// and must ensure its lifetime is longer than the FlatBufferModelBase
430	  /// instance. Returns a nullptr in case of failure.
431	  static std::unique_ptr<T> BuildFromModel(
432	      const tflite::Model* caller_owned_model_spec,
433	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter()) {
434	    error_reporter = ValidateErrorReporter(error_reporter);
435	
436	    if (CheckBufferOutsideModel(caller_owned_model_spec)) {
437	      TF_LITE_REPORT_ERROR(error_reporter,
438	                           "The model contains weights not accessible from "
439	                           "tflite::Model *, please use other api");
440	      return nullptr;
441	    }
442	
443	    std::unique_ptr<T> model(new T(caller_owned_model_spec, error_reporter));
444	    if (!model->initialized()) {
445	      model.reset();
446	    } else {
447	      model->ValidateModelBuffers(error_reporter);
448	    }
449	    return model;
450	  }
