452	  // Releases memory or unmaps mmaped memory.
453	  ~FlatBufferModelBase() = default;
454	
455	  // Copying or assignment is disallowed to simplify ownership semantics.
456	  FlatBufferModelBase(const FlatBufferModelBase&) = delete;
457	  FlatBufferModelBase& operator=(const FlatBufferModelBase&) = delete;
458	
459	  bool initialized() const { return model_ != nullptr; }
460	  const tflite::Model* operator->() const { return model_; }
