465	  // Returns the minimum runtime version from the flatbuffer. This runtime
466	  // version encodes the minimum required interpreter version to run the
467	  // flatbuffer model. If the minimum version can't be determined, an empty
468	  // string will be returned.
469	  // Note that the returned minimum version is a lower-bound but not a strict
470	  // lower-bound; ops in the graph may not have an associated runtime version,
471	  // in which case the actual required runtime might be greater than the
472	  // reported minimum.
473	  std::string GetMinimumRuntime() const {
474	    if (!model_ || !model_->metadata()) return "";
475	
476	    for (int i = 0; i < model_->metadata()->size(); ++i) {
477	      auto metadata = model_->metadata()->Get(i);
478	      if (metadata->name()->str() == tflite_metadata_min_runtime_version) {
479	        auto buf = metadata->buffer();
480	        auto* buffer = (*model_->buffers())[buf];
481	        auto* array = buffer->data();
482	        // Get the real length of the runtime string, since there might be
483	        // trailing
484	        // '\0's in the buffer.
485	        for (int len = 0; len < array->size(); ++len) {
486	          if (array->data()[len] == '\0') {
487	            return std::string(reinterpret_cast<const char*>(array->data()),
488	                               len);
489	          }
490	        }
491	        // If there is no '\0' in the buffer, this indicates that the flatbuffer
492	        // is malformed.
493	        TF_LITE_REPORT_ERROR(
494	            error_reporter_,
495	            "Min_runtime_version in model metadata is malformed");
496	        break;
497	      }
498	    }
499	    return "";
500	  }
501	
502	  // Return model metadata as a mapping of name & buffer strings.
503	  // See Metadata table in TFLite schema.
504	  std::map<std::string, std::string> ReadAllMetadata() const {
505	    return ReadAllMetadata(model_);
506	  }
507	
508	  // // Return model metadata as a mapping of name & buffer strings.
509	  // // See Metadata table in TFLite schema.
510	  static std::map<std::string, std::string> ReadAllMetadata(
511	      const ::tflite::Model* model) {
512	    std::map<std::string, std::string> keys_values;
513	    if (!model || !model->metadata() || !model->buffers()) return keys_values;
514	
515	    for (size_t i = 0; i < model->metadata()->size(); ++i) {
516	      auto metadata = model->metadata()->Get(i);
517	      auto buf = metadata->buffer();
518	      if (buf >= model->buffers()->size()) continue;
519	      const tflite::Buffer* buffer = (*model->buffers())[buf];
520	      if (!buffer || !buffer->data()) continue;
521	      const flatbuffers::Vector<uint8_t>* array = buffer->data();
522	      if (!array) continue;
523	      std::string val = std::string(
524	          reinterpret_cast<const char*>(array->data()), array->size());
525	      // Skip if key or value of metadata is empty.
526	      if (!metadata->name() || val.empty()) continue;
527	      keys_values[metadata->name()->str()] = val;
528	    }
529	    return keys_values;
530	  }
531	
532	  // Validates if the FlatBufferModelBase's buffer is well-formed. Specifically,
533	  // it checks if the 0th entry of the model buffers is an empty buffer
534	  // (sentinel). This is a convention so that tensors without a buffer can
535	  // provide 0 as their buffer. NOTE: The function doesn't explicitly fail for
536	  // backward compatibility reasons; it just provides a warning in case of
537	  // failures.
538	  void ValidateModelBuffers(ErrorReporter* error_reporter) {
539	    if (!allocation_) {
540	      auto buffers = model_->buffers();
541	      if (buffers && !buffers->empty()) {
542	        auto first_buffer = buffers->Get(0);
543	        if (first_buffer && first_buffer->size() != 0) {
544	          TF_LITE_REPORT_ERROR(
545	              error_reporter,
546	              "The 0th entry of the model buffer must be an empty buffer.");
547	        }
548	      }
549	      return;
550	    }
551	
552	    const uint8_t* base = reinterpret_cast<const uint8_t*>(allocation_->base());
553	    size_t bytes = allocation_->bytes();
554	    const uint8_t* model_ptr = reinterpret_cast<const uint8_t*>(model_);
555	
556	    // Validate the Model table VT_BUFFERS (12) field
557	    if (model_ptr < base ||
558	        model_ptr + sizeof(flatbuffers::soffset_t) > base + bytes) {
559	      return;
560	    }
561	    flatbuffers::soffset_t vtable_offset =
562	        flatbuffers::ReadScalar<flatbuffers::soffset_t>(model_ptr);
563	    const uint8_t* vtable = model_ptr - vtable_offset;
564	    if (vtable < base ||
565	        vtable + sizeof(flatbuffers::voffset_t) > base + bytes) {
566	      return;
567	    }
568	    flatbuffers::voffset_t vtable_size =
569	        flatbuffers::ReadScalar<flatbuffers::voffset_t>(vtable);
570	    if (vtable + vtable_size > base + bytes) return;
571	
572	    if (vtable_size <= 12) return;
573	
574	    flatbuffers::voffset_t field_offset =
575	        flatbuffers::ReadScalar<flatbuffers::voffset_t>(vtable + 12);
576	    if (field_offset == 0) return;
577	
578	    const uint8_t* field_ptr = model_ptr + field_offset;
579	    if (field_ptr < base ||
580	        field_ptr + sizeof(flatbuffers::uoffset_t) > base + bytes) {
581	      return;
582	    }
583	
584	    flatbuffers::uoffset_t vector_offset =
585	        flatbuffers::ReadScalar<flatbuffers::uoffset_t>(field_ptr);
586	    const uint8_t* vector_ptr = field_ptr + vector_offset;
587	    if (vector_ptr < base ||
588	        vector_ptr + sizeof(flatbuffers::uoffset_t) > base + bytes) {
589	      return;
590	    }
591	
592	    flatbuffers::uoffset_t vector_size =
593	        flatbuffers::ReadScalar<flatbuffers::uoffset_t>(vector_ptr);
594	    if (vector_ptr + sizeof(flatbuffers::uoffset_t) +
595	            vector_size * sizeof(flatbuffers::uoffset_t) >
596	        base + bytes) {
597	      return;
598	    }
599	
600	    if (vector_size == 0) return;
601	
602	    // Bounds check first_buffer (index 0)
603	    const uint8_t* element_offset_ptr =
604	        vector_ptr + sizeof(flatbuffers::uoffset_t);
605	    flatbuffers::uoffset_t element_offset =
606	        flatbuffers::ReadScalar<flatbuffers::uoffset_t>(element_offset_ptr);
607	    const uint8_t* first_buffer_ptr = element_offset_ptr + element_offset;
608	    if (first_buffer_ptr < base ||
609	        first_buffer_ptr + sizeof(flatbuffers::soffset_t) > base + bytes) {
610	      return;
611	    }
612	
613	    flatbuffers::soffset_t b_vtable_offset =
614	        flatbuffers::ReadScalar<flatbuffers::soffset_t>(first_buffer_ptr);
615	    const uint8_t* b_vtable = first_buffer_ptr - b_vtable_offset;
616	    if (b_vtable < base ||
617	        b_vtable + sizeof(flatbuffers::voffset_t) > base + bytes) {
618	      return;
619	    }
620	
621	    flatbuffers::voffset_t b_vtable_size =
622	        flatbuffers::ReadScalar<flatbuffers::voffset_t>(b_vtable);
623	    if (b_vtable + b_vtable_size > base + bytes) return;
624	
625	    // buffers[0] is structurally valid.
626	    // Make sure VT_SIZE (8) is also bounds check safe if
627	    // present
628	    if (8 < b_vtable_size) {
629	      flatbuffers::voffset_t b_field_offset =
630	          flatbuffers::ReadScalar<flatbuffers::voffset_t>(b_vtable + 8);
631	      if (b_field_offset != 0 &&
632	          first_buffer_ptr + b_field_offset + sizeof(uint64_t) > base + bytes) {
633	        return;  // Invalid field offset
634	      }
635	    }
636	
637	    auto buffers = model_->buffers();
638	    if (buffers && !buffers->empty()) {
639	      auto first_buffer = buffers->Get(0);
640	      if (first_buffer && first_buffer->size() != 0) {
641	        TF_LITE_REPORT_ERROR(error_reporter,
642	                             "The 0th entry of the model buffer must be an "
643	                             "empty buffer.");
644	      }
645	    }
646	  }
647	
648	  /// Returns true if the model identifier is correct (otherwise false and
649	  /// reports an error).
650	  bool CheckModelIdentifier() const {
651	    if (allocation_->bytes() < 7) {
652	      TF_LITE_REPORT_ERROR(
653	          error_reporter_,
654	          "Model provided must have at least 7 bytes to hold identifier.\n");
655	      return false;
656	    }
657	    if (!tflite::ModelBufferHasIdentifier(allocation_->base())) {
658	      const char* ident = flatbuffers::GetBufferIdentifier(allocation_->base());
659	      // Suppress unused variable warning.
660	      (void)ident;
661	      TF_LITE_REPORT_ERROR(
662	          error_reporter_,
663	          "Model provided has model identifier '%c%c%c%c', should be '%s'\n",
664	          ident[0], ident[1], ident[2], ident[3], tflite::ModelIdentifier());
665	      return false;
666	    }
667	    return true;
668	  }
669	
670	  /// Check If the buffer is stored as part of the Flatbuffer or outside
671	  /// Return false if the buffers are part of the Flatbuffer
672	  static bool CheckBufferOutsideModel(const tflite::Model* model) {
673	    if (!model || !model->metadata()) return false;
674	
675	    for (int i = 0; i < model->metadata()->size(); ++i) {
676	      auto metadata = model->metadata()->Get(i);
677	      if (metadata->name()->str() == tflite_metadata_buffer_location) {
678	        return true;
679	      }
680	    }
681	    return false;
682	  }
683	
684	 protected:
685	  /// Loads a model from a given allocation. FlatBufferModelBase will take over
686	  /// the ownership of `allocation`, and delete it in destructor. The ownership
687	  /// of `error_reporter`remains with the caller and must have lifetime at least
688	  /// as much as FlatBufferModelBase. This is to allow multiple models to use
689	  /// the same ErrorReporter instance.
690	  explicit FlatBufferModelBase(
691	      std::unique_ptr<Allocation> allocation,
692	      ErrorReporter* error_reporter = T::GetDefaultErrorReporter())
693	      : error_reporter_(ValidateErrorReporter(error_reporter)),
694	        allocation_(std::move(allocation)) {
695	    if (!allocation_ || !allocation_->valid() || !CheckModelIdentifier()) {
696	      return;
697	    }
698	
699	    const uint8_t* base = reinterpret_cast<const uint8_t*>(allocation_->base());
700	    size_t bytes = allocation_->bytes();
701	    if (bytes < sizeof(flatbuffers::uoffset_t)) {
702	      TF_LITE_REPORT_ERROR(error_reporter_,
703	                           "The model is not a valid Flatbuffer buffer");
704	      return;
705	    }
706	    flatbuffers::uoffset_t root_offset =
707	        flatbuffers::ReadScalar<flatbuffers::uoffset_t>(base);
708	    if (root_offset < sizeof(flatbuffers::uoffset_t) || root_offset >= bytes) {
709	      TF_LITE_REPORT_ERROR(error_reporter_,
710	                           "The model is not a valid Flatbuffer buffer");
711	      return;
712	    }
713	
714	    const uint8_t* model_ptr = base + root_offset;
715	    if (model_ptr < base ||
716	        model_ptr + sizeof(flatbuffers::soffset_t) > base + bytes) {
717	      TF_LITE_REPORT_ERROR(error_reporter_,
718	                           "The model is not a valid Flatbuffer buffer");
719	      return;
720	    }
721	    flatbuffers::soffset_t vtable_offset =
722	        flatbuffers::ReadScalar<flatbuffers::soffset_t>(model_ptr);
723	    const uint8_t* vtable = model_ptr - vtable_offset;
724	    if (vtable < base ||
725	        vtable + sizeof(flatbuffers::voffset_t) > base + bytes) {
726	      TF_LITE_REPORT_ERROR(error_reporter_,
727	                           "The model is not a valid Flatbuffer buffer");
728	      return;
729	    }
730	    flatbuffers::voffset_t vtable_size =
731	        flatbuffers::ReadScalar<flatbuffers::voffset_t>(vtable);
732	    if (vtable + vtable_size > base + bytes) {
733	      TF_LITE_REPORT_ERROR(error_reporter_,
734	                           "The model is not a valid Flatbuffer buffer");
735	      return;
736	    }
737	
738	    model_ = ::tflite::GetModel(allocation_->base());
739	  }
740	
741	  /// Loads a model from Model flatbuffer. The `model` has to remain alive and
742	  /// unchanged until the end of this flatbuffer model's lifetime.
743	  FlatBufferModelBase(const Model* model, ErrorReporter* error_reporter)
744	      : model_(model), error_reporter_(ValidateErrorReporter(error_reporter)) {}
745	
746	  static ErrorReporter* ValidateErrorReporter(ErrorReporter* error_reporter) {
747	    return error_reporter ? error_reporter : T::GetDefaultErrorReporter();
748	  }
749	
750	  /// Flatbuffer traverser pointer. (Model* is a pointer that is within the
751	  /// allocated memory of the data allocated by allocation's internals.
752	  const tflite::Model* model_ = nullptr;
753	  /// The error reporter to use for model errors and subsequent errors when
754	  /// the interpreter is created
755	  ErrorReporter* error_reporter_;
756	  /// The allocator used for holding memory of the model. Note that this will
757	  /// be null if the client provides a tflite::Model directly.
758	  std::unique_ptr<Allocation> allocation_;
759	};
760	
761	}  // namespace impl
762	
763	}  // namespace tflite
764	
765	#endif  // TENSORFLOW_COMPILER_MLIR_LITE_CORE_MODEL_BUILDER_BASE_H_
766

